{
  "root": "main_stack",
  "state": {
    "itinerary_data": [
      {
        "day": "Day 1",
        "title": "Arrival & Historic Markets",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Nishiki_Market_Kyoto_Japan.jpg/1200px-Nishiki_Market_Kyoto_Japan.jpg",
        "imageAlt": "Nishiki Market Kyoto Japan",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/shop.svg",
        "description": "Check into lodging and head to Nishiki Market for local snacks.\nWalk through the Teramachi shopping arcade for kid-friendly stores."
      },
      {
        "day": "Day 2",
        "title": "Arashiyama Adventures",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Arashiyama_Bamboo_Grove_Kyoto.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto.jpg",
        "imageAlt": "Arashiyama Bamboo Grove Kyoto",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "description": "Walk through the Bamboo Grove and visit the Iwatayama Monkey Park.\nTake a traditional boat ride on the Hozugawa River."
      },
      {
        "day": "Day 3",
        "title": "Nara Day Trip",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Nara_Park_Deer_2011.jpg/1200px-Nara_Park_Deer_2011.jpg",
        "imageAlt": "Nara Park Deer",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "description": "Feed the friendly bowing deer in Nara Park.\nVisit Todai-ji Temple to see the Great Buddha (Daibutsu)."
      },
      {
        "day": "Day 4",
        "title": "Samurai & Castles",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Nijo_Castle_Kyoto.jpg/1200px-Nijo_Castle_Kyoto.jpg",
        "imageAlt": "Nijo Castle Kyoto",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "description": "Participate in a kid-friendly Samurai Experience (swords and armor).\nExplore the \"chirping\" nightingale floors of Nijo Castle.",
        "actionLabel": "Samurai Museum",
        "actionUrl": "https://www.samuraishow.com"
      },
      {
        "day": "Day 5",
        "title": "Tea & Traditions",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Kiyomizu-dera_in_Kyoto-r.jpg/1200px-Kiyomizu-dera_in_Kyoto-r.jpg",
        "imageAlt": "Kiyomizu-dera in Kyoto",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg",
        "description": "Attend a family tea ceremony in a traditional Machiya.\nVisit Kiyomizu-dera Temple and explore the Sannenzaka streets.",
        "actionLabel": "Tea Ceremony",
        "actionUrl": "https://www.tea-kyoto.com"
      },
      {
        "day": "Day 6",
        "title": "Fushimi Inari & Departure",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Fushimi_Inari_shrine_2016.jpg/1200px-Fushimi_Inari_shrine_2016.jpg",
        "imageAlt": "Fushimi Inari shrine",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/signpost-split.svg",
        "description": "Hike through the thousands of vermilion torii gates at Fushimi Inari.\nPick up souvenirs at Kyoto Station before departure."
      }
    ],
    "neighborhood_comparison": [
      {
        "Neighborhood": "Gion",
        "Atmosphere": "Traditional/Historical",
        "Family Fit": "High",
        "Lodging Type": "Machiya Houses"
      },
      {
        "Neighborhood": "Shimogyo",
        "Atmosphere": "Modern/Convenient",
        "Family Fit": "Very High",
        "Lodging Type": "Large Hotels"
      },
      {
        "Neighborhood": "Nakagyo",
        "Atmosphere": "Central/Shopping",
        "Family Fit": "High",
        "Lodging Type": "Boutique/Apartments"
      }
    ],
    "budget_breakdown": [
      { "item": "Lodging (5 nights)", "cost": "$1,000" },
      { "item": "Food ($150/day)", "cost": "$900" },
      { "item": "Transport", "cost": "$300" },
      { "item": "Activities", "cost": "$300" },
      { "item": "Total", "cost": "$2,500" }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "lg", "padding": 16 },
      "children": [
        "title_kyoto_expedition",
        "hero_card",
        "itinerary_heading",
        "itinerary_table",
        "neighborhood_heading",
        "neighborhood_table",
        "budget_heading",
        "budget_table",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_kyoto_expedition": {
      "type": "Text",
      "props": { "text": "Kyoto Family Expedition", "variant": "h1" },
      "children": []
    },
    "hero_card": {
      "type": "Card",
      "props": {},
      "children": [
        "hero_image",
        "hero_description"
      ]
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Fushimi_Inari_shrine_2016.jpg/1200px-Fushimi_Inari_shrine_2016.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "hero_description": {
      "type": "Text",
      "props": {
        "text": "A 6-day family itinerary focusing on a balance of historical immersion and interactive fun for children. This plan keeps the total spend under the $2,500 USD limit."
      },
      "children": []
    },
    "itinerary_heading": {
      "type": "Text",
      "props": { "text": "6-Day Itinerary", "variant": "h2" },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary_data",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "title",
        "highlightColumns": ["day"],
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "title", "label": "Activity" },
          { "key": "image", "label": "Image" },
          { "key": "imageAlt", "label": "Image Alt" },
          { "key": "icon", "label": "Icon" },
          { "key": "description", "label": "Details" },
          { "key": "actionLabel", "label": "Action" },
          { "key": "actionUrl", "label": "URL" }
        ]
      },
      "children": []
    },
    "neighborhood_heading": {
      "type": "Text",
      "props": { "text": "Neighborhood Comparison Table", "variant": "h2" },
      "children": []
    },
    "neighborhood_table": {
      "type": "Table",
      "props": {
        "statePath": "/neighborhood_comparison",
        "domain": "comparison",
        "preferredPresentation": "table",
        "primaryColumn": "Neighborhood",
        "columns": [
          { "key": "Neighborhood", "label": "Neighborhood" },
          { "key": "Atmosphere", "label": "Atmosphere" },
          { "key": "Family Fit", "label": "Family Fit" },
          { "key": "Lodging Type", "label": "Lodging Type" }
        ]
      },
      "children": []
    },
    "budget_heading": {
      "type": "Text",
      "props": { "text": "Budget Breakdown", "variant": "h2" },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "statePath": "/budget_breakdown",
        "domain": "formula",
        "preferredPresentation": "table",
        "columns": [
          { "key": "item", "label": "Item" },
          { "key": "cost", "label": "Cost" }
        ],
        "highlightColumns": ["cost"]
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": { "text": "Quick Actions", "variant": "h2" },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": [
        "button_jr_timetable",
        "button_kyoto_events"
      ]
    },
    "button_jr_timetable": {
      "type": "Button",
      "props": { "label": "JR West Timetable" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://www.westjr.co.jp/global/en/" }
        }
      },
      "children": []
    },
    "button_kyoto_events": {
      "type": "Button",
      "props": { "label": "Kyoto Event Calendar" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://kyoto.travel/en/index.html" }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": { "text": "Sources", "variant": "h2" },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": [
        "button_inside_kyoto",
        "button_japan_guide"
      ]
    },
    "button_inside_kyoto": {
      "type": "Button",
      "props": { "label": "Inside Kyoto Guide" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://www.insidekyoto.com" }
        }
      },
      "children": []
    },
    "button_japan_guide": {
      "type": "Button",
      "props": { "label": "Japan-Guide Kyoto" },
      "on": {
        "press": {
          "action": "openUrl",
          "params": { "url": "https://www.japan-guide.com/e/e3950.html" }
        }
      },
      "children": []
    }
  }
}
